<?php
// Handler revenue: được gọi duy nhất bởi api/index.php sau xác thực localhost và CSRF.
if (!defined('EZ_API_ENTRY')) { http_response_code(404); exit; }
    if ($action==='revenue' && $method==='GET') {
        [$start,$end]=rangeDates((string)($_GET['range']??'month'));
        $totals=one($db,"SELECT COUNT(*) transactions, COALESCE(SUM(CASE WHEN p.status='success' AND p.payment_type IN ('deposit','final') THEN p.amount ELSE 0 END),0) received, COALESCE(SUM(CASE WHEN p.status='success' AND p.payment_type='deposit' THEN p.amount ELSE 0 END),0) deposits, COALESCE(SUM(CASE WHEN p.status='success' AND p.payment_type='final' THEN p.amount ELSE 0 END),0) finals, COALESCE(SUM(CASE WHEN p.payment_type='refund' AND p.status IN ('success','refunded') THEN p.amount ELSE 0 END),0) refunds, SUM(p.status='success' AND p.payment_type='deposit') paid_deposits FROM payments p WHERE p.paid_at>=? AND p.paid_at<?",[$start,$end]);
        $byLot=rows($db,"SELECT l.id,l.name,l.status, COUNT(DISTINCT CASE WHEN p.status='success' AND p.payment_type='deposit' THEN r.id ELSE NULL END) bookings, COALESCE(SUM(CASE WHEN p.status='success' AND p.payment_type='deposit' THEN p.amount ELSE 0 END),0) deposits, COALESCE(SUM(CASE WHEN p.status='success' AND p.payment_type='final' THEN p.amount ELSE 0 END),0) finals, COALESCE(SUM(CASE WHEN p.status='success' AND p.payment_type IN ('deposit','final') THEN p.amount ELSE 0 END),0) received, COALESCE(SUM(CASE WHEN p.payment_type='refund' AND p.status IN ('success','refunded') THEN p.amount ELSE 0 END),0) refunds, COALESCE(SUM(CASE WHEN p.status='success' AND p.payment_type='deposit' AND r.status='forfeited' THEN p.amount ELSE 0 END),0) forfeited_deposits FROM parking_lots l LEFT JOIN reservations r ON r.parking_lot_id=l.id LEFT JOIN payments p ON p.reservation_id=r.id AND p.paid_at>=? AND p.paid_at<? GROUP BY l.id ORDER BY received DESC,l.id",[$start,$end]);
        $byProvider=rows($db,"SELECT provider, COUNT(*) transactions, COALESCE(SUM(CASE WHEN status='success' AND payment_type IN ('deposit','final') THEN amount ELSE 0 END),0) received FROM payments WHERE paid_at>=? AND paid_at<? GROUP BY provider ORDER BY received DESC",[$start,$end]);
        $byVehicle=rows($db,"SELECT v.vehicle_type,COALESCE(SUM(CASE WHEN p.status='success' AND p.payment_type IN ('deposit','final') THEN p.amount ELSE 0 END),0) received,COUNT(DISTINCT p.reservation_id) bookings FROM payments p JOIN reservations r ON r.id=p.reservation_id JOIN vehicles v ON v.id=r.vehicle_id WHERE p.paid_at>=? AND p.paid_at<? GROUP BY v.vehicle_type ORDER BY received DESC",[$start,$end]);
        $recent=rows($db,'SELECT p.id,p.reservation_id,p.provider,p.payment_type,p.amount,p.status,p.transaction_ref,p.paid_at,l.name lot_name FROM payments p JOIN reservations r ON r.id=p.reservation_id JOIN parking_lots l ON l.id=r.parking_lot_id WHERE p.paid_at>=? AND p.paid_at<? ORDER BY p.paid_at DESC,p.id DESC LIMIT 200',[$start,$end]);
        $byDay=rows($db,"SELECT DATE(paid_at) day, COALESCE(SUM(CASE WHEN status='success' AND payment_type='deposit' THEN amount ELSE 0 END),0) deposits, COALESCE(SUM(CASE WHEN status='success' AND payment_type='final' THEN amount ELSE 0 END),0) finals FROM payments WHERE paid_at>=? AND paid_at<? GROUP BY DATE(paid_at) ORDER BY DATE(paid_at) DESC LIMIT 120",[$start,$end]);
        $byDay=array_reverse($byDay);
        $settings=one($db,"SELECT setting_value FROM app_settings WHERE setting_key='commission_percent'");
        reply(['range'=>['from'=>$start,'to'=>$end],'totals'=>$totals,'byLot'=>$byLot,'byProvider'=>$byProvider,'byVehicle'=>$byVehicle,'byDay'=>$byDay,'recent'=>$recent,'commission'=>(float)($settings['setting_value']??10)]);
    }
